    rows, cols = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] != 0}
    placements = []
    for r in range(rows - 1):
        for c in range(cols - 1):
            block = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            placements.append((block, 1))
            for missing, color in [
                ((r, c), 2),       # top-left
                ((r + 1, c), 3),   # bottom-left
                ((r, c + 1), 4),   # top-right
                ((r + 1, c + 1), 5),  # bottom-right
            ]:
                placements.append((block - {missing}, color))

    by_cell = {cell: [] for cell in occupied}
    for shape, color in placements:
        if shape:
            for cell in shape:
                if cell in by_cell:
                    by_cell[cell].append((shape, color))

    def cover(remaining, painted):
        if not remaining:
            return painted.copy()
        cell = min(remaining, key=lambda p: sum(shape <= remaining for shape, _ in by_cell[p]))
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                for p in shape:
                    painted[p] = color
                result = cover(remaining - shape, painted)
                if result is not None:
